function air75CapMask(shape: { viewBox: string; d: string }): string {
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${shape.viewBox}" preserveAspectRatio="none">` +
    `<path d="${shape.d}"/></svg>`;
  return `url("data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}") center / 100% 100% no-repeat`;
}

